// The offline Surya Siddhanta calculator against the Rust server's own
// numbers: positions and derivations are the direct formulas (not the table),
// so this test proves the TypeScript interpolation reproduces them.
// Fixtures generated by `siddhanta-table fixtures` / `sun` from the
// 2000 table in ./fixtures (see apps/rust/crates/siddhanta-table/README.md).
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

import {
  displaySpeedAt,
  grahaAt,
  karanaAt,
  lagnaAt,
  nextNakshatraBoundary,
  nextTithiBoundary,
  parseSiddhantaTable,
  positionsAt,
  stabSource,
  sunriseSunset,
  tithiAt,
  yogaAt,
} from "../src/astronomy/siddhanta-offline";

const KATHMANDU_LAT = 27.7172;
const KATHMANDU_LON = 85.324;

interface Fixture {
  jd: number;
  longitude: number[];
  speed: number[];
  ayanamsha: number;
  mean_sun_sayana: number;
  tithi: number;
  tithi_progress: number;
  nakshatra: number;
  pada: number;
  nakshatra_progress: number;
  yoga: number;
  yoga_progress: number;
  karana: number;
  karana_progress: number;
  moon_rashi: number;
  sun_rashi: number;
  lagna: number;
}

interface SunFixture {
  start_jd: number;
  sunrise_jd: number;
  sunset_jd: number;
}

function loadFixtures(): { table: ReturnType<typeof parseSiddhantaTable>; rows: Fixture[]; sun: SunFixture[] } {
  // The table is stored base64 (the snapshot push cannot carry binary
  // files); decoding it gives back the exact STAB bytes.
  const tableB64 = readFileSync(new URL("./fixtures/siddhanta-2000.vtab.b64", import.meta.url), "utf8");
  const table = parseSiddhantaTable(new Uint8Array(Buffer.from(tableB64.trim(), "base64")));
  const rows = JSON.parse(
    readFileSync(new URL("./fixtures/siddhanta-2000.json", import.meta.url), "utf8"),
  ) as Fixture[];
  const sun = JSON.parse(
    readFileSync(new URL("./fixtures/siddhanta-2000-sun.json", import.meta.url), "utf8"),
  ) as SunFixture[];
  return { table, rows, sun };
}

function angleClose(actual: number, expected: number, toleranceDegrees: number): void {
  let diff = ((actual - expected) % 360 + 540) % 360 - 180;
  diff = Math.abs(diff);
  assert.ok(diff <= toleranceDegrees, `expected ${actual} within ${toleranceDegrees}° of ${expected}`);
}

test("interpolated longitudes match the server's direct formulas", () => {
  const { table, rows } = loadFixtures();
  // The text's own arithmetic steps every ~14 s, so the Moon can be ~5" out
  // and the rest under 1" — the tolerances below carry that floor with room.
  const tolerance = [0.001, 0.003, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001];
  for (const row of rows) {
    const positions = positionsAt(table, row.jd);
    assert.ok(positions !== null, `JD ${row.jd} is inside the table`);
    for (let b = 0; b < 8; b += 1) {
      angleClose(positions.longitude[b], row.longitude[b], tolerance[b]);
    }
    assert.ok(Math.abs(positions.ayanamsha - row.ayanamsha) < 0.001, `ayanamsha JD ${row.jd}`);
    assert.ok(
      Math.abs(positions.meanSunSayana - row.mean_sun_sayana) < 0.001,
      `mean Sun JD ${row.jd}`,
    );
  }
});

test("display speeds, from the table's own ±0.5-day difference, match the server's", () => {
  const { table, rows } = loadFixtures();
  const bodies = ["sun", "moon", "mars", "mercury", "jupiter", "venus", "saturn", "rahu"] as const;
  for (const row of rows) {
    for (let b = 0; b < 8; b += 1) {
      const speed = displaySpeedAt(stabSource(table), row.jd, bodies[b]);
      assert.ok(speed !== null, `JD ${row.jd} ${bodies[b]} is inside the table`);
      assert.ok(
        Math.abs(speed - row.speed[b]) < 0.005,
        `JD ${row.jd} ${bodies[b]}: ${speed} vs ${row.speed[b]}`,
      );
    }
  }
});

test("tithi, nakshatra, pada, yoga and karana match the server", () => {
  const { table, rows } = loadFixtures();
  for (const row of rows) {
    const positions = positionsAt(table, row.jd);
    assert.ok(positions !== null);
    const sun = positions.longitude[0];
    const moon = positions.longitude[1];
    const tithi = tithiAt(sun, moon);
    assert.equal(tithi.number, row.tithi, `tithi JD ${row.jd}`);
    assert.ok(Math.abs(tithi.progress - row.tithi_progress) < 0.002, `tithi progress JD ${row.jd}`);
    const graha = grahaAt(moon);
    assert.equal(graha.nakshatra, row.nakshatra, `nakshatra JD ${row.jd}`);
    assert.equal(graha.pada, row.pada, `pada JD ${row.jd}`);
    assert.ok(
      Math.abs(graha.nakshatraProgress - row.nakshatra_progress) < 0.002,
      `nakshatra progress JD ${row.jd}`,
    );
    assert.equal(graha.rashi, row.moon_rashi, `Moon rashi JD ${row.jd}`);
    assert.equal(grahaAt(sun).rashi, row.sun_rashi, `Sun rashi JD ${row.jd}`);
    const yoga = yogaAt(sun, moon);
    assert.equal(yoga.number, row.yoga, `yoga JD ${row.jd}`);
    assert.ok(Math.abs(yoga.progress - row.yoga_progress) < 0.002, `yoga progress JD ${row.jd}`);
    const karana = karanaAt(sun, moon);
    assert.equal(karana.number, row.karana, `karana JD ${row.jd}`);
    assert.ok(Math.abs(karana.progress - row.karana_progress) < 0.002, `karana progress JD ${row.jd}`);
  }
});

test("lagna matches the server for Kathmandu", () => {
  const { table, rows } = loadFixtures();
  for (const row of rows) {
    const lagna = lagnaAt(stabSource(table), row.jd, KATHMANDU_LAT, KATHMANDU_LON);
    assert.ok(lagna !== null);
    angleClose(lagna, row.lagna, 0.02);
  }
});

test("sunrise and sunset match the server's solver for Kathmandu", () => {
  const { table, sun } = loadFixtures();
  for (const day of sun) {
    const found = sunriseSunset(stabSource(table), day.start_jd, KATHMANDU_LAT, KATHMANDU_LON);
    assert.ok(found.sunriseJd !== null, `sunrise ${day.start_jd}`);
    assert.ok(found.sunsetJd !== null, `sunset ${day.start_jd}`);
    assert.ok(
      Math.abs(found.sunriseJd - day.sunrise_jd) < 0.0014,
      `sunrise ${day.start_jd}: ${found.sunriseJd} vs ${day.sunrise_jd}`,
    );
    assert.ok(
      Math.abs(found.sunsetJd - day.sunset_jd) < 0.0014,
      `sunset ${day.start_jd}: ${found.sunsetJd} vs ${day.sunset_jd}`,
    );
  }
});

test("next tithi and nakshatra boundaries land on a real change", () => {
  const { table, rows } = loadFixtures();
  const row = rows[0];
  const positions = positionsAt(table, row.jd);
  assert.ok(positions !== null);
  const tithiBoundary = nextTithiBoundary(stabSource(table), row.jd);
  assert.ok(tithiBoundary !== null && tithiBoundary > row.jd);
  const before = positionsAt(table, tithiBoundary - 1 / 1440);
  const after = positionsAt(table, tithiBoundary + 1 / 1440);
  assert.ok(before !== null && after !== null);
  assert.notEqual(
    tithiAt(before.longitude[0], before.longitude[1]).number,
    tithiAt(after.longitude[0], after.longitude[1]).number,
  );
  const nakshatraBoundary = nextNakshatraBoundary(stabSource(table), row.jd);
  assert.ok(nakshatraBoundary !== null && nakshatraBoundary > row.jd);
  const nBefore = positionsAt(table, nakshatraBoundary - 1 / 1440);
  const nAfter = positionsAt(table, nakshatraBoundary + 1 / 1440);
  assert.ok(nBefore !== null && nAfter !== null);
  assert.notEqual(
    grahaAt(nBefore.longitude[1]).nakshatra,
    grahaAt(nAfter.longitude[1]).nakshatra,
  );
});

test("a bad magic and a truncated file are rejected", () => {
  const { table } = loadFixtures();
  const bytes = new Uint8Array(table.bytes);
  const wrongMagic = bytes.slice();
  wrongMagic[0] = 88; // 'X'
  assert.throws(() => parseSiddhantaTable(wrongMagic), /bad magic/);
  assert.throws(() => parseSiddhantaTable(bytes.slice(0, 40)), /too short/);
  assert.throws(() => parseSiddhantaTable(bytes.slice(0, 48 + 10)), /sample count/);
});
